import React from "react";
import { Link } from "react-router-dom";

function Signup() {
  return (
    <div style={{ padding: 40, textAlign: "center" }}>
      <h2>Signup</h2>
      <p>Use the full signup form</p>
      <Link to="/auth/signup">
        <button style={{ padding: 8, marginTop: 12 }}>Go to Signup</button>
      </Link>
    </div>
  );
}

export default Signup;
